{"file_path": "src/openforms/accounts/tests/factories.py", "original_signature": "def user_permissions(self, create, extracted, **kwargs):", "target_file": {"ok": true, "path": "src/openforms/accounts/tests/factories.py", "sha": "b35bccfec9c977c4f8eab78889722259396e121c", "download_url": "https://raw.githubusercontent.com/open-formulieren/open-forms/e07e33706cfb5fa6e99a509bbce40d9e9db1d329/src/openforms/accounts/tests/factories.py", "content_excerpt": "from django.conf import settings
from django.contrib.auth.models import Permission

import factory


class UserFactory(factory.django.DjangoModelFactory):
    username = factory.Sequence(lambda n: f"user-{n}")
    password = factory.PostGenerationMethodCall("set_password", "secret")

    @factory.post_generation
    def user_permissions(self, create, extracted, **kwargs):
        if not create:
            return

        if extracted:
            for permission in extracted:
                if isinstance(permission, str):
                    # TODO support appname/model/action, for now lets assume we have unique codenames
                    permission = Permission.objects.get(codename=permission)
                self.user_permissions.add(permission)

    class Meta:
        model = "accounts.User"

    @classmethod
    def mock_two_factor_flow(cls, user, app):
        # Mock the user having gone through the two factor authentication flow
        app.set_cookie(settings.SESSION_COOKIE_NAME, "initial")
        session = app.session
        session["otp_device_id"] = user.staticdevice_set.create().persistent_id
        session.save()
        app.set_cookie(settings.SESSION_COOKIE_NAME, session.session_key)

    @classmethod
    def create(cls, **kwargs):
        app = kwargs.pop("app", None)
        user = super().create(**kwargs)

        if app:
            cls.mock_two_factor_flow(user, app)

        return user


class StaffUserFactory(UserFactory):
    is_staff = True


class SuperUserFactory(StaffUserFactory):
    is_superuser = True


class TokenFactory(factory.django.DjangoModelFactory):
    user = factory.SubFactory(UserFactory)

    class Meta:
        model = "authtoken.Token"
