def hexstr(x, onlyasc=0, onlyhex=0):
    s = []
    if not onlyasc:
        s.append(" ".join(map(lambda x:"%02x"%ord(x), x)))
    if not onlyhex:
        s.append(sane(x)) 
    return "  ".join(s)

def repr_hex(s):
    """ Convert provided bitstring to a simple string of hex digits """
    return "".join(map(lambda x: "%02x" % ord(x),s))

